			/* <flatten type="Javascript"> */
function load$CheckingReport$(g) {
	g._$k = [];
	g._$i = g._getColumnOrder('ma_kh');
	g._$t = g._getColumnOrder('tag');
	g._$f = 'keys';
	g.add_commandEvent(on$GridCheckingReport$ExecuteCommand);
}
function scatter$GridReport$(g) {
	fill$Grid(g, true);
	var c = g._getColumnOrder('sysprint');
	var t = g._getColumnOrder('tag')
	for (var i = 1; i <= g._rowCount; i++) {
		if (g._getItemValue(i, c) == 0) g._getItem(i, t).disabled = true;
	}
	if (g._rowCount > 0) {
		g._activeRow = g._rowCount;
		g._activeColumn = g._$t;
		g._activeCell = g._getItem(g._activeRow, g._activeColumn);
	}
}
function dispose$CheckingReport$(g) {
	g._$k = g._$i = g._$t = null;
	try {g.remove_commandEvent(on$GridCheckingReport$ExecuteCommand);} catch (ex) {}
}
function on$GridCheckingReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'Print':
			e.type.cancelEvent = !isCheck$Grid(g);
			init$ExportKey(g, ',');
			break;
		default:
			break;
	}
}
/* </flatten> */

function zDrillDown(o, n){
	var g = o.grid, f = g.get_element().parentForm;
	var p = window.location.href.split('?')[0];
	zpassQueryParameters(g);
}
function zpassQueryParameters(g) {&Parameter;
		var part = String.fromCharCode(253);
		var lstArrVal = g._queryFilterString.split(part);
		var a = [
		{Name: 'tk', Value: lstArrVal[3]},
		{Name: 'tu_ngay', Value: parseYYYYMMDD(lstArrVal[1])},
		{Name: 'den_ngay', Value: parseYYYYMMDD(lstArrVal[2])},
		{Name: 'ma_kh', Value: g._getItemValue(g._activeRow, g._getColumnOrder('ma_kh'))},
		{Name: 'ten_kh', Value: g._getItemValue(g._activeRow, g._getColumnOrder('ten_kh'))},
		{Name: 'nh_kh1', Value: ''},
		{Name: 'nh_kh2', Value: ''},
		{Name: 'nh_kh3', Value: ''},
		{Name: 'ma_dvcs', Value: lstArrVal[4]},
		{Name: 'mau_bc', Value: lstArrVal[5]},
		{Name: 'tt_sx1', Value: 0},
		{Name: 'tt_sx2', Value: 0},
		{Name: 'tt_sx3', Value: 0},
		{Name: 'sx_theo', Value: 0}
	];
	var session = {Memvar: a, Script: 'this._convection = true;'&Session;};
	_zpassParameter(g, session);

}
function _zpassParameter(g, session) {
				var t = Math.random().toString(36).replace(/[^a-z]+/g, "").substr(0, 6);
				var p = window.location.href.split('?')[0];
				g.Parameter = t,
				sessionStorage.setItem(t, Sys.Serialization.JavaScriptSerializer.serialize(session));
				var base = p.substring(0, p.lastIndexOf("/") + 1);
				var url = base + 'rpt_arcd1.aspx?p=' + t;

				console.log(url);
				window.open(url);
}
function parseYYYYMMDD(str) {
    return new Date(
        str.substring(0,4),
        str.substring(4,6) - 1,
        str.substring(6,8)
    );
}



